public class KubeJSNet {
	private static final Map<String, NetworkManager> CHANNELS = new HashMap<>();

	public static void registerChannel(String id, int version) {
		var channel = NetworkManager.ChannelKonstruktor(
			new ResourceLocation("kubejs", id),
			version,
			NetworkDirection.PLAY_TO_CLIENT
		);
		CHANNELS.put(id, channel);
	}

	public static void registerReceiver(String channel, String id, Consumer<PacketContext> receiver) {
		var manager = CHANNELS.get(channel);
		if (manager != null) {
			manager.registerMessage(id, PacketImpl.class, (packet, buf) -> {
				// decode
			}, (buf) -> {
				// encode
			}, (packet, context) -> {
				receiver.accept(context);
			});
		}
	}

	public static void sendToServer(Object message) {
		KubeJS.CHANNEL.sendToServer(message);
	}

	public static void sendTo(Player player, Object message) {
		KubeJS.CHANNEL.send(PacketDistributor.PLAYER.apply(player), message);
	}

	public static void sendToAll(Object message) {
		KubeJS.CHANNEL.send(PacketDistributor.ALL.apply(message), message);
	}
}
